import Selector from '../../Selector/Selector';
import './PanelVentas.css'
import Input from "../../Input/Input";
import Tarjeta from '../../ComponentesFormulario/Tarjeta/Tarjeta';
import Boton from '../../Boton/Boton';
import Radio from '../../Radio/Radio'
import { useState, useEffect } from 'react';
import BotonPerfil from '../../BotonPerfil/BotonPerfil';
import { useForm, useWatch } from 'react-hook-form';
import meses from '../../../Datos_Pruebas/Meses.json'
import { XyzTransition } from "@animxyz/react";
import { useFuncionesPerfil } from '../../../hooks/useFuncionesPerfil';
import leyseca from '../../../assets/leysecalogo.png'

export default function PanelVentas({ onDatosFiltrados, onManejaCargando, id_sucursal, onSeleccionarSucursal, permisoVerInforme, token, onMostrarInformes, onMostrarInformeGeneral, onFiltros, esSuperAdmin }) {



    ////////// SELECCION DE LA OPCION DEL RADIO
    const [seleccion, setSeleccion] = useState('');//valor por defecto
    const manejarSeleccion = (valor) => {
        setSeleccion(valor);
    };

    // función para obtener la fecha en formato YYYY-MM-DD
    const obtenerFechaHoy = () => {
        const hoy = new Date();
        const year = hoy.getFullYear();
        const mes = String(hoy.getMonth() + 1).padStart(2, '0');
        const dia = String(hoy.getDate()).padStart(2, '0');
        return `${year}-${mes}-${dia}`;
    };



    ///////// HOOK FORM

    const { register, control, setValue, formState: { errors } } = useForm({
        defaultValues: {
            periodo_ventas: "Todas las ventas", // Valor por defecto
            fecha_desde: obtenerFechaHoy(),
            fecha_hasta: obtenerFechaHoy()
        }
    });

    // Observar en tiempo real el valor del radio button
    const periodoVentas = useWatch({
        control,
        name: "periodo_ventas"
    });

    /////////CAPTURAR LOS VALORES DEL FORMULARIO DINAMICAMENTE
    const filtro = useWatch({ control });


    const obtenerDatosFiltrados = async (data = filtro) => { //funcion que hace la consulta dependiendo los filtros
        onManejaCargando(true);
        try {

            const respuestaVenta = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/venta/filtro`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Accept': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: JSON.stringify(data),
            });


            const datos = await respuestaVenta.json();
           console.log(datos)   
            const datosTransformados = datos.map(item => ({
                Numero_Venta: item.id_venta,
                Neto: `$ ${item.total}`,
                Fecha: new Date(item.fecha).toLocaleDateString(),
                Descuento_Gral: `${item.descuento_gral || 0} %`,
                Total: `$ ${(
                    parseFloat(item.total.replace(',', '.')) * (1 - item.descuento_gral / 100)
                ).toFixed(2).replace('.', ',')}`, //arreglado

                Vendedor: `${item.usuario.nombre} ${item.usuario.apellido}`,
                Metodo_Pago: item.metodo_pago,
            }));
            onDatosFiltrados(datosTransformados);
            onFiltros(filtro);
        } catch (error) {
            console.error('Error en la solicitud:', error);
        } finally {
            onManejaCargando(false);
        }
    };


    useEffect(() => {
        if (!filtro?.id_sucursal && esSuperAdmin) return;
        obtenerDatosFiltrados(filtro);
        onSeleccionarSucursal(filtro.id_sucursal);
    }, [filtro])


    //aqui se guardan los años obtenidos del backend
    const [aniosVenta, setAniosVenta] = useState([]);

    //////////// BUSCA SUCURSALES EN EL BACKEND
    const [sucursales, setSucursales] = useState([]);

    useEffect(() => {
        const obtenerSucursales = async () => {
            try {
                const respuesta = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/sucursal`);
                const datos = await respuesta.json();
                setSucursales(datos);

                // 👉 Si hay al menos una sucursal, establecerla como valor por defecto
                if (datos.length > 0) {
                    setValue("id_sucursal", datos[0].id_sucursal);
                }
            } catch (error) {
                console.log(error);
            }
        };

        obtenerSucursales();
    }, [setValue]);

    //USEEFFECT PARA OBTENER TODOS LOS AñOS DE LAS COMPRAS

    useEffect(() => {
        const obtenerAnios = async () => {
            try {
                const respuesta = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/venta/anios`);
                const data = await respuesta.json();

                // El backend devuelve algo como: [2023, 2024, 2025]
                const opcionesAnios = data.map(anio => ({
                    label: anio.toString(),
                    value: anio.toString()
                }));

                setAniosVenta(opcionesAnios);
            } catch (error) {
                console.error('Error al obtener años de ventas:', error);
            }
        };

        obtenerAnios();
    }, []);





    return (
        <>
            <div className='__panel_ventas'>
                <div className='__logo_background'>
                    <img src={leyseca} alt="Ley Seca Logo" />
                </div>
                <form>
                    {esSuperAdmin ? (<div className='__columna1_superAdmin'>
                        {esSuperAdmin && <Tarjeta descripcion="Sucursal" forid="sucursal" mensajeError={errors.id_sucursal?.message}>
                            <Selector
                                id="sucursal"
                                opciones={sucursales.map(suc => ({ label: suc.nombre, value: suc.id_sucursal }))}
                                {...register("id_sucursal", { required: { value: true, message: "Ingrese Sucursal" } })}
                                opcionDefecto
                            />
                        </Tarjeta>}
                        <Tarjeta descripcion="Metodo de Pago" forid="metodo_pago">
                            <Selector opciones={[{ label: "Efectivo", value: "Efectivo" }, { label: "Transferencia", value: "Transferencia" },
                            { label: "Tarjeta Debito", value: "Tarjeta Debito" }, { label: "Tarjeta Credito", value: "Tarjeta Credito" }]}
                                id="metodo_pago"
                                opcionNula="Todos"
                                {...register("metodo_pago")}
                            />
                        </Tarjeta>
                    </div>) : (<div className='__columna1'>
                        <Tarjeta descripcion="Metodo de Pago" forid="metodo_pago">
                            <Selector opciones={[{ label: "Efectivo", value: "Efectivo" }, { label: "Transferencia", value: "Transferencia" }]}
                                id="metodo_pago"
                                opcionNula="Todos"
                                {...register("metodo_pago")}
                            />
                        </Tarjeta>
                    </div>)}

                    <div className='__columna2'>
                        <div className='__linea_vertical'></div>
                        <Radio opciones={["Ventas del mes de", "Ver ventas desde el", "Todas las ventas"]}
                            name="periodo_ventas"
                            value={periodoVentas}
                            onChange={(valor) => setValue("periodo_ventas", valor)} // Actualiza el valor en hook form
                        ></Radio>
                    </div>
                    <div className='__columna3'>
                        <div className='__fila1'>
                            <Selector
                                opciones={meses}
                                id="mes_venta"
                                deshabilitado={periodoVentas !== "Ventas del mes de"}
                                {...register("mes_venta")}
                            />
                            <Selector opciones={aniosVenta}
                                id="anio_venta"
                                deshabilitado={periodoVentas !== "Ventas del mes de"}
                                {...register("anio_venta")}
                            />
                        </div>
                        <div className='__fila2'>
                            <Input tipo="date"
                                id="fecha_desde"
                                deshabilitado={periodoVentas !== "Ver ventas desde el"}
                                {...register("fecha_desde")}
                            ></Input>
                            <label>al</label>
                            <Input tipo="date"
                                id="fecha_hasta"
                                deshabilitado={periodoVentas !== "Ver ventas desde el"}
                                {...register("fecha_hasta")}
                            ></Input>
                        </div>
                    </div>
                    <div className='__columna4'>
                        {permisoVerInforme && <Boton habilitado descripcion="Informe de Ventas" onClick={() => onMostrarInformes(true)} title="Ver métricas de venta de esta sucursal"></Boton>}
                        {(permisoVerInforme && esSuperAdmin) && <Boton habilitado descripcion="Informe General" onClick={() => onMostrarInformeGeneral(true)} title="Ver métricas de ingresos y egresos de todas las sucursales"></Boton>}
                    </div>
                </form>
            </div>
        </>
    )
}