import { useEffect, useState } from "react";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, LineChart, Line } from "recharts";
import "./Informes.css";
import Boton from "../Boton/Boton";
import no_encontrado from "../../assets/no_encontrado.png";
import TarjetaProducto from "../TarjetaProducto/TarjetaProducto";
import { useExportarDatos } from "../../hooks/useExportarDatos";

export default function Informes({ filtros, token, onCerrar }) {

  //HOOK PARA CONVERTIR DATOS EN EXCELL Y PDF
  const { exportarInformeVentasAExcel, exportarInformeVentasAPDF } = useExportarDatos();

  const manejarExportacion = (tipo) => {
    const datosExportacion = {
      metricas,
      ventasPorFecha,
      productosMasVendidos,
      combosMasVendidos,
      topVendedores
    };

    if (tipo === 'excel') {
      exportarInformeVentasAExcel(datosExportacion, 'informe_ventas.xlsx', getPeriodoTexto());
    } else if (tipo === 'pdf') {
      exportarInformeVentasAPDF(datosExportacion, 'informe_ventas.pdf', getPeriodoTexto());
    }
  };



  //////////FUNCION PRIMMERA LETRA DE UNA PALABRA EN MAYUSCULAS
  const transformaMayusucula = (str) => {
    return str.replace(/\b\w/g, (char) => char.toUpperCase());
  };

  // Función para formatear moneda
  const formatearMoneda = (monto) => {
    return `$ ${monto.toLocaleString('es-AR', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    })}`;
  };

  const [metricas, setMetricas] = useState({
    total_vendido: 0,
    cantidad_ventas: 0,
    productos_vendidos: 0,
    combos_vendidos: 0,
  });



  const [ventasPorFecha, setVentasPorFecha] = useState([]);
  const [productosMasVendidos, setProductosMasVendidos] = useState([]);
  const [combosMasVendidos, setCombosMasVendidos] = useState([]);
  const [topVendedores, setTopVendedores] = useState([]);
  const [cargando, setCargando] = useState(false);

  useEffect(() => {
    if (filtros && Object.keys(filtros).length > 0) obtenerInforme();
  }, [filtros]);

  const obtenerInforme = async () => {
    try {
      setCargando(true);
  const res = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/venta/informe`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Accept": "application/json",
          "Authorization": `Bearer ${token}`,
        },
        body: JSON.stringify(filtros),
      });

      if (!res.ok) throw new Error("Error al generar el informe");
      const data = await res.json();

      setMetricas(data.metricas);


      // Mantener Total como número para el gráfico
      const ventasFormateadas = data.ventas_por_fecha.map(venta => ({
        fecha: venta.fecha,
        Total: venta.Total  // Mantener como número
      }));
      setVentasPorFecha(ventasFormateadas);

      console.log(data.productos_mas_vendidos);
      //  transformar productos al guardar
      const productosTransformados = data.productos_mas_vendidos.map(producto => ({
        ...producto,
        producto: transformaMayusucula(producto.producto)
      }));
      setProductosMasVendidos(productosTransformados);

      //igual para combos
      const combosTransformados = data.combos_mas_vendidos.map(combo => ({
        ...combo,
        nombre: transformaMayusucula(combo.nombre)
      }));
      setCombosMasVendidos(combosTransformados);

      setTopVendedores(data.top_vendedores);
      console.log(data.top_vendedores);
    } catch (error) {
      console.error("Error al obtener informe:", error);
    } finally {
      setCargando(false);
    }
  };

  if (cargando) return <p>Cargando informe...</p>;

  // Eprodcuto y combo más vendido
  const topProducto = productosMasVendidos[0];
  const topCombo = combosMasVendidos[0];


  //formateo correcto de fechas

  const formatearFecha = (fechaISO) => {
    if (!fechaISO) return "";
    const [anio, mes, dia] = fechaISO.split("-");
    return `${dia}/${mes}/${anio}`;
  };

  const getPeriodoTexto = () => {
    const nombresMeses = [
      "Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio",
      "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"
    ];

    if (filtros.periodo_ventas === 'Todas las ventas') {
      return "Todas las Ventas";
    } else if (filtros.periodo_ventas === 'Ver ventas desde el') {
      return `Desde ${formatearFecha(filtros.fecha_desde)} Hasta ${formatearFecha(filtros.fecha_hasta)}`;
    } else {
      return `${nombresMeses[Number(filtros.mes_venta) - 1]} del ${filtros.anio_venta}`;
    }
  };

  //consigue imagen del item

  // Función para construir la URL completa de la imagen
  const construirUrlImagen = (rutaRelativa, esCombo, esSucursal) => {
    if (!rutaRelativa) return no_encontrado
    // Si ya contiene http, devuelve tal cual (por si acaso)
    if (rutaRelativa.startsWith('http')) return rutaRelativa
    // Si comienza con /, le agregamos el endpoint
    if (esCombo || esSucursal) {
      return `${API_ENDPOINT}${rutaRelativa}`
    }
  return `${import.meta.env.VITE_API_BASE_URL}/storage/${rutaRelativa}`
  }




  // console.log(construirUrlImagen(`${import.meta.env.VITE_API_BASE_URL}/api/storage/${topProducto.foto}`));

  return (
    <div className="__informe_modal">
      <div className="__informe_contenido">
        <h2 style={{ textAlign: 'center' }}>📊 Informe de Ventas - {getPeriodoTexto()} </h2>

        {/* MÉTRICAS */}
        <div className="__informe_cards">

          <div className="__card_informe">
            <h4>Ventas Totales</h4>
            <p>{metricas.cantidad_ventas}</p>
          </div>
          <div className="__card_informe">
            <h4>Productos Vendidos</h4>
            <p>{metricas.productos_vendidos}</p>
          </div>
          <div className="__card_informe">
            <h4>Combos Vendidos</h4>
            <p>{metricas.combos_vendidos}</p>
          </div>
          <div className="__card_informe">
            <h4>Total Recaudado</h4>
            <p>$ {metricas.total_vendido.toLocaleString()}</p>
          </div>
        </div>

        {/* PRODUCTOS MÁS VENDIDOS */}
        <div className="__seccion_grafico">

          <div className="__grafico">
            <div className="separador"></div>
            <h3 style={{ marginBottom: "3rem" }}>Productos más vendidos</h3>
            {productosMasVendidos.length ?
              <ResponsiveContainer width="100%" height={300}>
                <BarChart data={productosMasVendidos} >
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="producto" tick={{ fill: '#333', fontSize: 15 }}
                    angle={-25}
                    textAnchor="end"
                    height={100} />
                  <YAxis tick={{ fill: '#333' }} />
                  <Tooltip contentStyle={{ backgroundColor: '#f9f9f9', border: '2px solid #ddd', fontWeight: 'bold' }} />
                  <Bar dataKey="cantidad" fill="#9e030d"  // ROJO
                    radius={[10, 10, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
              : <h3 style={{ display: 'flex', justifyContent: 'center', margin: '2rem 0rem' }}>No hay productos vendidos en este período</h3>
            }
          </div>
          {topProducto && (
            <div className="__tarjeta_top">
              <h4 style={{ marginBottom: "2rem" }}>🏆 Producto más vendido</h4>
              <TarjetaProducto nombre={transformaMayusucula(topProducto.producto)}
                precio={topProducto.costo}
                cantidad={topProducto.cantidad}
                imagen={construirUrlImagen(topProducto.foto)}
              ></TarjetaProducto>
            </div>
          )}
        </div>

        {/*  COMBOS MÁS VENDIDOS */}
        <div className="__seccion_grafico">
          <div className="__grafico">
            <div className="separador"></div>
            <h3> Combos más vendidos</h3>
            {combosMasVendidos.length ?
              <ResponsiveContainer width="100%" height={300}>
                <BarChart data={combosMasVendidos}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="nombre" tick={{ fill: '#333', fontSize: 15 }} angle={-25}
                    textAnchor="end"
                    height={100} />
                  <YAxis tick={{ fill: '#333' }} />
                  <Tooltip
                    contentStyle={{ backgroundColor: '#f9f9f9', border: '2px solid #ddd', fontWeight: 'bold' }}
                  />
                  <Bar dataKey="cantidad" fill="#efc169"  // DORADO
                    radius={[10, 10, 0, 0]} />
                </BarChart>
              </ResponsiveContainer> : <h3 style={{ display: 'flex', justifyContent: 'center', margin: '2rem 0rem' }}>No hay combos vendidos en este período</h3>}
          </div>
          {topCombo && (
            <div className="__tarjeta_top" >
              <h4 style={{ marginBottom: "2rem" }}>🎁 Combo más vendido</h4>
              <TarjetaProducto nombre={transformaMayusucula(topCombo.nombre)}
                cantidad={topCombo.cantidad}
                imagen={construirUrlImagen(topCombo.foto)}
                precio={topCombo.costo}
              ></TarjetaProducto>
            </div>
          )}
        </div>

        {/* EVOLUCIÓN DE VENTAS */}
        <div className="__seccion_grafico">
          <div className="__grafico">
            <div className="separador"></div>
            <h3>Evolución de ventas</h3>
            {ventasPorFecha.length ?
              <ResponsiveContainer width="100%" height={300}>
                <LineChart data={ventasPorFecha}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="fecha" />
                  <YAxis />
                  <Tooltip
                    contentStyle={{ backgroundColor: '#f9f9f9', border: '2px solid #ddd', fontWeight: 'bold' }}
                    formatter={(value) => formatearMoneda(value)}
                    labelFormatter={(label) => `Fecha: ${label}`}
                  />
                  <Line type="monotone" dataKey="Total" stroke="#9e030d" strokeWidth={2} />
                </LineChart>
              </ResponsiveContainer>
              :
              <h3 style={{ display: 'flex', justifyContent: 'center', margin: '2rem 0rem' }}>No hay ventas en este período</h3>
            }
          </div>

          <div className="__tarjeta_top">
            <h4>🏅 Top Vendedores</h4>
            {topVendedores.length > 0 ? (
              <ul>
                {topVendedores.map((v, i) => (
                  <li key={i}>
                    <b>#{i + 1} {transformaMayusucula(v.nombre)}, {transformaMayusucula(v.apellido)}</b> – {v.ventas} ventas
                  </li>
                ))}
              </ul>
            ) : (
              <p>No hay registros.</p>
            )}
          </div>
        </div>


      <div className="__informe_ventaPorSucursal_footer">
        <Boton onClick={() => manejarExportacion('excel')} habilitado descripcion={"Descargar EXCEL"} />
        <Boton onClick={() => manejarExportacion('pdf')} habilitado descripcion={"Descargar PDF"} />
      </div>
      </div>
    </div>
  );
}
