import TablaConPaginacion from "../../Componentes/TablaConPaginacion/TablaConPaginacion";
import PanelVentas from '../../Componentes/Paneles/PanelVentas/PanelVentas'
import PlantillaPages from '../../Componentes/PlantillaPages/PlantillaPages'
import Pestanias from "../../Componentes/Pestanias/Pestanias";
import Boton from "../../Componentes/Boton/Boton";
import { useState, useEffect } from 'react'
import columnas from '../../Datos_Pruebas/Columnas_Ventas.json'
import columnasVenta from '../../Datos_Pruebas/Columnas_Unica_Venta.json'
import Modal from '../../Componentes/Modal/Modal'
import './Ventas.css'
import Informes from "../../Componentes/Informes/Informes";
import { useValidarSesion } from "../../hooks/useValidarSesion";
import { m } from "framer-motion";
import { set } from "react-hook-form";
import InformeGeneral from "../../Componentes/InformeGeneral/InformeGeneral";


export default function Ventas({ }) {



  const { storeCargado, usuario, token } = useValidarSesion(); // obtener el token desde Zustand




  //BOOLEANO DEFINE SI ES SUPERADMIN
  const esSuperAdmin = usuario?.rol?.[0]?.nombreRol === "superadmin";

  //ESTADO PARA DETERMINAR LA SUCURSAL
  const [idSucursalSeleccionada, setIdSucursalSeleccionada] = useState(
    esSuperAdmin ? null : usuario?.sucursal?.[0]?.id_sucursal || null
  );
  console.log('idSucursalSeleccionada en ventas:', idSucursalSeleccionada);

  //BOOLEANO PARA PREGUNTAR SI EL USUARIO TIENE PERMISO DE VER INFORME DE VENTAS
  const permisoVerInforme = usuario?.permisos?.some(
    (permiso) => permiso.nombrePermiso === 'ver informe'
  ) ||
    usuario?.permisos_extra?.some(
      (permiso) => permiso.nombrePermiso === 'ver informe'
    );

  ////////MANEJA MODAL DE DETALLES

  const [modalDetallesVenta, setModalDetallesVenta] = useState(false);

  const manejaVerDetalles = () => {
    setModalDetallesVenta(!modalDetallesVenta);
    if (modalDetallesVenta) {
      setElementoSeleccionado(null);
    }
  };



  /////// FUNCION QUE SE LE PASA AL PANEL PARA RECUPERAR LOS DATOS FILTRADOS
  const [datos, setDatos] = useState([]);
  const [datosFiltrados, setDatosFiltrados] = useState([]); //datos para mandar al modal de informes
  const obtieneDatosFiltrados = (datosFiltrados) => {
    setDatos(datosFiltrados);
    // Filtra solo los campos que necesitas
    const datosSimplificados = datosFiltrados.map(item => ({
      numero_venta: item.numero_venta || item.Numero_Venta,
      vendedor: item.vendedor || item.Vendedor
    }));
    setDatosFiltrados(datosSimplificados);
  };

  //////////FUNCION PRIMMERA LETRA DE UNA PALABRA EN MAYUSCULAS
  const transformaMayusucula = (str) => {
    return str.replace(/\b\w/g, (char) => char.toUpperCase());
  };


  /////////SE ENCARGA DE LA SELECCION DE UNA VENTA EN LA TABLA Y DE HABILITAR EL BOTON PARA Visualizar

  const [elementoSeleccionado, setElementoSeleccionado] = useState(null);
  const manejarSeleccion = (elemento) => {
    setElementoSeleccionado(elemento);
  };



  const [venta, setVenta] = useState(null);

  useEffect(() => {
    if (elementoSeleccionado) {
  fetch(`${import.meta.env.VITE_API_BASE_URL}/api/venta/${elementoSeleccionado.Numero_Venta}`)
        .then(respuesta => respuesta.json())
        .then(venta => {
          console.log(venta);
          const datosVentaTransformados = venta.productos.map(item => (
            {
              Codigo: item.codigo,
              Item: transformaMayusucula(item.nombre),
              Cantidad: item.cantidad,
              Subtotal: `$ ${(parseFloat(item.costo.replace(',', '.')) * item.cantidad).toFixed(2).replace('.', ',')}`,
              IVA: `${item.iva} %`,
              Descuento: item.tipo === "producto" ? `${item.descuento_porcentaje === null ? 0 : item.descuento_porcentaje} %` : 'Es Combo',
              TOTAL: !item.es_combo ? `$ ${(
                (parseFloat(item.costo.replace(',', '.')) *
                  (1 + item.iva / 100) * // Agrega el IVA
                  (1 - (item.descuento_porcentaje === null ? 0 : item.descuento_porcentaje / 100))) * // Aplica el descuento 
                item.cantidad).toFixed(2).replace('.', ',')}` : `$ ${(parseFloat(item.costo.replace(',', '.')) * item.cantidad).toFixed(2).replace('.', ',')}`

            }));
          setVenta(datosVentaTransformados);
        })
        .catch(e => console.log(e));
    }
  }, [elementoSeleccionado]);

  

  /////////// ESTADO PARA SABER CUANDO SE ESTA CARGANDO (SE ESTAN TRAYENDO LOS DATOS)
  const [cargando, setCargando] = useState(false);
  const manejaCargando = ((valor) => {
    setCargando(valor);
  });

  ///////ESTADO Y FUNCION PARA MANEJAR EL MODAL DE INFORMES
  const [modalInformes, setModalInformes] = useState(false);
  const manejaModalInformes = ((valor) => {
    setModalInformes(valor);
  });


  // ESTADO Y FUNCION PARA MANEJAR EL MODAL DE INFORMES GENERALES
const [modalInformeGeneral, setModalInformeGeneral] = useState(false);
const manejaModalInformeGeneral = ((valor) => {
    setModalInformeGeneral(valor);
});

  ///para traer los filtros del panelfiltros
  const [filtros, setFiltros] = useState({});

  //  PROTECCIÓN: si todavia no se cargo el store ni usuario, no reendreizar nada
  if (!storeCargado || !usuario || !token) {
    return <div className="__cargando_modal"></div>;
  }





  //////LAYOUT

  const header = <PanelVentas onDatosFiltrados={obtieneDatosFiltrados}
    onManejaCargando={manejaCargando}
    esSuperAdmin={esSuperAdmin}
    token={token}
    onMostrarInformes={manejaModalInformes}
    onMostrarInformeGeneral={manejaModalInformeGeneral}
    onFiltros={setFiltros}
    permisoVerInforme={permisoVerInforme}
    onSeleccionarSucursal={setIdSucursalSeleccionada}
  ></PanelVentas>


  const main = <TablaConPaginacion columnas={columnas} datos={datos} itemsPorPagina={5}
    itemsPorPaginaOpcional onElementoSeleccionado={manejarSeleccion} cargando={cargando}>

  </TablaConPaginacion>

  const navigation = <Pestanias></Pestanias>

  const footer = <div className="__footer_ventas">
    <Boton descripcion={"VER"} onClick={manejaVerDetalles} habilitado={elementoSeleccionado} title="Ver detalles de la venta"></Boton>
    <Modal visible={modalDetallesVenta} titulo="Detalles de la Venta" funcion={manejaVerDetalles} anchura={"800px"} >
      {!venta ? (
        <div className="__cargando_modal">Cargando venta...</div>
      ) : (
        <TablaConPaginacion columnas={columnasVenta} datos={venta} itemsPorPagina={5}></TablaConPaginacion>
      )}
    </Modal>
    <Modal visible={modalInformes} titulo="Informe de Ventas" funcion={() => manejaModalInformes(false)} anchura={"80%"} >
      <Informes
        filtros={filtros}
        token={token}
        onCerrar={() => manejaModalInformes(false)}
      />
    </Modal>

    <Modal visible={modalInformeGeneral} titulo="Informe General de Ingreso/Egreso" funcion={() => manejaModalInformeGeneral(false)} anchura={"90%"} >
        <InformeGeneral
            metodoPago ={filtros.metodo_pago}
            filtros={filtros}
            token={token}
            onCerrar={() => manejaModalInformeGeneral(false)}
        />
    </Modal>



  </div>

  return <PlantillaPages
    header={header}
    navigation={navigation}
    main={main}
    footer={footer}
    nombreUsuario={usuario?.nombre}
    apellidoUsuario={usuario?.apellido}
    sucursal={usuario?.sucursal?.[0]?.nombreSucursal}
    id_sucursal={idSucursalSeleccionada}
    rol={usuario?.rol?.[0]?.nombreRol}
    esSuperAdmin={esSuperAdmin}
    token={token}
  />;
}
