import { useEffect, useState } from "react";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, LineChart, Line } from "recharts";
import "./InformeGeneral.css";
import Boton from "../Boton/Boton";
import ingreso from "../../assets/ingreso.png";
import egreso from "../../assets/egreso.png";
import { useExportarDatos } from "../../hooks/useExportarDatos";

export default function InformeGeneral({ filtros, token, onCerrar, metodoPago }) {
    const { exportarAExcel, exportarAPDF } = useExportarDatos();
    console.log(metodoPago)

    const [tipoInforme, setTipoInforme] = useState('ingreso'); // 'ingreso' o 'egreso'
    const [metricas, setMetricas] = useState({
        total_vendido: 0,
        cantidad_ventas: 0,
        productos_vendidos: 0,
        combos_vendidos: 0,
        total_compras: 0,
        cantidad_compras: 0,
        productos_comprados: 0,
    });

    const [datosSucursales, setDatosSucursales] = useState([]);
    const [cargando, setCargando] = useState(false);

    const formatearMoneda = (monto) => {
        return `$ ${monto.toLocaleString('es-AR', {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2
        })}`;
    };

    const formatearFecha = (fechaISO) => {
        if (!fechaISO) return "";
        const [anio, mes, dia] = fechaISO.split("-");
        return `${dia}/${mes}/${anio}`;
    };

    const nombresMeses = [
        "Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio",
        "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"
    ];

    const transformaMayusucula = (str) => {
        return str.replace(/\b\w/g, (char) => char.toUpperCase());
    };

    const manejarExportacion = (tipo) => {
        const periodo = (
            filtros.periodo_ventas === 'Todas las ventas' ? "Todas las Ventas" :
                (filtros.periodo_ventas === 'Ver ventas desde el' ?
                    `Desde el ${formatearFecha(filtros.fecha_desde)} al ${formatearFecha(filtros.fecha_hasta)}` :
                    `${nombresMeses[Number(filtros.mes_venta) - 1]} del ${filtros.anio_venta}`)
        );

        const datosExportacion = {
            metricas,
            sucursales: datosSucursales,
            tipoInforme,
        };

        if (tipo === 'excel') {
            exportarAExcel(datosExportacion, 'informe_ventas.xlsx', periodo, tipoInforme);
        } else if (tipo === 'pdf') {
            exportarAPDF(datosExportacion, 'informe_ventas.pdf', periodo, tipoInforme);
        }
    };

    useEffect(() => {
        obtenerInformeGeneral();
    }, []);

    const obtenerInformeGeneral = async () => {
        try {
            setCargando(true);
            const res = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/venta/informe-general`, {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    "Accept": "application/json",
                    "Authorization": `Bearer ${token}`,
                },
                body: JSON.stringify(filtros),
            });

            if (!res.ok) throw new Error("Error al generar el informe general");
            const data = await res.json();

            setMetricas(data.metricas);

            const datosSucursalesTransformados = data.sucursales.map(sucursal => ({
                id_sucursal: sucursal.id_sucursal,
                nombre_sucursal: sucursal.nombre_sucursal,
                productos_mas_vendidos: sucursal.productos_mas_vendidos.map(producto => ({
                    ...producto,
                    producto: transformaMayusucula(producto.producto)
                })),
                productos_menos_vendidos: sucursal.productos_menos_vendidos.map(producto => ({
                    ...producto,
                    producto: transformaMayusucula(producto.producto)
                })),
                combos_mas_vendidos: sucursal.combos_mas_vendidos.map(combo => ({
                    ...combo,
                    nombre: transformaMayusucula(combo.nombre)
                })),
                combos_menos_vendidos: sucursal.combos_menos_vendidos.map(combo => ({
                    ...combo,
                    nombre: transformaMayusucula(combo.nombre)
                })),
                ventas_por_fecha: sucursal.ventas_por_fecha.map(venta => ({
                    fecha: venta.fecha,
                    Total: venta.Total
                })),
                productos_comprados: sucursal.productos_comprados || []
            }));

            setDatosSucursales(datosSucursalesTransformados);
        } catch (error) {
            console.error("Error al obtener informe general:", error);
        } finally {
            setCargando(false);
        }
    };

    const getPeriodoTexto = () => {
        return filtros.periodo_ventas === 'Todas las ventas' ? `Todas las ${tipoInforme === 'ingreso' ? 'Ventas' : 'Compras'}` :
            (filtros.periodo_ventas === 'Ver ventas desde el' ?
                `Desde el ${formatearFecha(filtros.fecha_desde)} al ${formatearFecha(filtros.fecha_hasta)}` :
                `${nombresMeses[Number(filtros.mes_venta) - 1]} del ${filtros.anio_venta}`);
    };

    if (cargando) return <p>Cargando informe general...</p>;

    return (
        <div className="__informe_general_modal">
            <div className="__informe_general_contenido">
                <div className="__encabezado_informe">
                    {tipoInforme === 'ingreso' ? 
                    ( <h2 style={{ textAlign: 'center', flex: 1 }}>
                        📊 Informe General de Ingresos - Todas las Sucursales - {getPeriodoTexto()} - Metodo de Pago: {metodoPago === '' ? `Todos` : metodoPago}</h2>)
                    :
                    ( <h2 style={{ textAlign: 'center', flex: 1 }}>
                        📉 Informe General de Egresos - Todas las Sucursales - {getPeriodoTexto()} </h2>)
                        }

                    <div className="__toggle_container">
                        <button
                            title="Ver informe de ingresos"
                            className={`__toggle_btn ${tipoInforme === 'ingreso' ? 'activo_ingreso' : ''} `}
                            onClick={() => setTipoInforme('ingreso')}
                        >
                            <img
                                src={ingreso}
                                alt="Ingreso"
                                className="icono_btn"
                            />

                        </button>

                        <button
                        title="Ver informe de egresos"
                            className={`__toggle_btn ${tipoInforme === 'egreso' ? 'activo_egreso' : ''}`}
                            onClick={() => setTipoInforme('egreso')}
                        >
                            <img
                                src={egreso}
                                alt="Egreso"
                                className="icono_btn"
                            />

                        </button>
                    </div>
                </div>

                {tipoInforme === 'ingreso' ? (
                    <>
                        {/* MÉTRICAS DE INGRESO */}
                        <div className="__informe_cards">
                            <div className="__card_informe">
                                <h4>Ventas Totales</h4>
                                <p>{metricas.cantidad_ventas}</p>
                            </div>
                            <div className="__card_informe">
                                <h4>Productos Vendidos</h4>
                                <p>{metricas.productos_vendidos}</p>
                            </div>
                            <div className="__card_informe">
                                <h4>Combos Vendidos</h4>
                                <p>{metricas.combos_vendidos}</p>
                            </div>
                            <div className="__card_informe">
                                <h4>Total Recaudado</h4>
                                <p>{formatearMoneda(metricas.total_vendido)}</p>
                            </div>
                        </div>

                        {/* PRODUCTOS MÁS VENDIDOS POR SUCURSAL */}
                        <div className="__seccion_horizontal">
                            <div className="separador"></div>
                            <h3>🏆 Top 10 Productos Más Vendidos por Sucursal</h3>
                            <div className="__contenedor_horizontal_scroll">
                                {datosSucursales.map((sucursal, idx) => (
                                    <div key={idx} className="__tarjeta_sucursal">
                                        <h4>{sucursal.nombre_sucursal}</h4>
                                        {sucursal.productos_mas_vendidos.length > 0 ? (
                                            <ResponsiveContainer width="100%" height={300}>
                                                <BarChart data={sucursal.productos_mas_vendidos}>
                                                    <CartesianGrid strokeDasharray="3 3" />
                                                    <XAxis
                                                        dataKey="producto"
                                                        tick={{ fill: '#333', fontSize: 12 }}
                                                        angle={-45}
                                                        textAnchor="end"
                                                        height={100}
                                                    />
                                                    <YAxis tick={{ fill: '#333' }} />
                                                    <Tooltip contentStyle={{ backgroundColor: '#f9f9f9', border: '2px solid #ddd', fontWeight: 'bold' }} />
                                                    <Bar
                                                        dataKey="cantidad"
                                                        fill="#9e030d"
                                                        radius={[10, 10, 0, 0]}
                                                    />
                                                </BarChart>
                                            </ResponsiveContainer>
                                        ) : (
                                            <p style={{ textAlign: 'center', margin: '2rem 0' }}>No hay productos vendidos</p>
                                        )}
                                    </div>
                                ))}
                            </div>
                        </div>

                        {/* COMBOS MÁS VENDIDOS POR SUCURSAL */}
                        <div className="__seccion_horizontal">
                            <div className="separador"></div>
                            <h3>🎁 Top 10 Combos Más Vendidos por Sucursal</h3>
                            <div className="__contenedor_horizontal_scroll">
                                {datosSucursales.map((sucursal, idx) => (
                                    <div key={idx} className="__tarjeta_sucursal">
                                        <h4>{sucursal.nombre_sucursal}</h4>
                                        {sucursal.combos_mas_vendidos.length > 0 ? (
                                            <ResponsiveContainer width="100%" height={300}>
                                                <BarChart data={sucursal.combos_mas_vendidos}>
                                                    <CartesianGrid strokeDasharray="3 3" />
                                                    <XAxis
                                                        dataKey="nombre"
                                                        tick={{ fill: '#333', fontSize: 12 }}
                                                        angle={-45}
                                                        textAnchor="end"
                                                        height={100}
                                                    />
                                                    <YAxis tick={{ fill: '#333' }} />
                                                    <Tooltip contentStyle={{ backgroundColor: '#f9f9f9', border: '2px solid #ddd', fontWeight: 'bold' }} />
                                                    <Bar
                                                        dataKey="cantidad"
                                                        fill="#efc169"
                                                        radius={[10, 10, 0, 0]}
                                                    />
                                                </BarChart>
                                            </ResponsiveContainer>
                                        ) : (
                                            <p style={{ textAlign: 'center', margin: '2rem 0' }}>No hay combos vendidos</p>
                                        )}
                                    </div>
                                ))}
                            </div>
                        </div>

                        {/* EVOLUCIÓN DE VENTAS POR SUCURSAL */}
                        <div className="__seccion_vertical_scroll">
                            <div className="separador"></div>
                            <h3>📈 Evolución de Ventas por Sucursal</h3>
                            <div className="__contenedor_graficos_evolucion">
                                {datosSucursales.map((sucursal, idx) => (
                                    <div key={idx} className="__grafico_evolucion">
                                        <h4>{sucursal.nombre_sucursal}</h4>
                                        {sucursal.ventas_por_fecha.length > 0 ? (
                                            <ResponsiveContainer width="100%" height={250}>
                                                <LineChart data={sucursal.ventas_por_fecha}>
                                                    <CartesianGrid strokeDasharray="3 3" />
                                                    <XAxis dataKey="fecha" tick={{ fill: '#333' }} />
                                                    <YAxis tick={{ fill: '#333' }} />
                                                    <Tooltip
                                                        contentStyle={{ backgroundColor: '#f9f9f9', border: '2px solid #ddd', fontWeight: 'bold' }}
                                                        formatter={(value) => formatearMoneda(value)}
                                                        labelFormatter={(label) => `Fecha: ${label}`}
                                                    />
                                                    <Line
                                                        type="monotone"
                                                        dataKey="Total"
                                                        stroke="#9e030d"
                                                        strokeWidth={2}
                                                    />
                                                </LineChart>
                                            </ResponsiveContainer>
                                        ) : (
                                            <p style={{ textAlign: 'center', margin: '2rem 0' }}>No hay ventas en este período</p>
                                        )}
                                    </div>
                                ))}
                            </div>
                        </div>
                    </>
                ) : (
                    <>
                        {/* MÉTRICAS DE EGRESO */}
                        <div className="__informe_cards">
                            <div className="__card_informe">
                                <h4>Compras Totales</h4>
                                <p>{metricas.cantidad_compras}</p>
                            </div>
                            <div className="__card_informe">
                                <h4>Productos Comprados</h4>
                                <p>{metricas.productos_comprados}</p>
                            </div>
                            <div className="__card_informe">
                                <h4>Total Invertido</h4>
                                <p>{formatearMoneda(metricas.total_compras)}</p>
                            </div>

                        </div>

                        {/* PRODUCTOS MENOS VENDIDOS POR SUCURSAL */}
                        <div className="__seccion_horizontal">
                            <div className="separador"></div>
                            <h3>🔻 Top 10 Productos Menos Vendidos por Sucursal</h3>
                            <div className="__contenedor_horizontal_scroll">
                                {datosSucursales.map((sucursal, idx) => (
                                    <div key={idx} className="__tarjeta_sucursal">
                                        <h4>{sucursal.nombre_sucursal}</h4>
                                        {sucursal.productos_menos_vendidos.length > 0 ? (
                                            <div className="__lista_productos">
                                                {sucursal.productos_menos_vendidos.map((prod, i) => (
                                                    <div key={i} className="__item_lista">
                                                        <span className="__rank">{i + 1}.</span>
                                                        <span className="__nombre">{prod.producto}</span>
                                                        <span className="__cantidad">{prod.cantidad}</span>
                                                    </div>
                                                ))}
                                            </div>
                                        ) : (
                                            <p style={{ textAlign: 'center', margin: '2rem 0' }}>No hay datos</p>
                                        )}
                                    </div>
                                ))}
                            </div>
                        </div>

                        {/* COMBOS MENOS VENDIDOS POR SUCURSAL */}
                        <div className="__seccion_horizontal">
                            <div className="separador"></div>
                            <h3>🔻 Top 10 Combos Menos Vendidos por Sucursal</h3>
                            <div className="__contenedor_horizontal_scroll">
                                {datosSucursales.map((sucursal, idx) => (
                                    <div key={idx} className="__tarjeta_sucursal">
                                        <h4>{sucursal.nombre_sucursal}</h4>
                                        {sucursal.combos_menos_vendidos.length > 0 ? (
                                            <div className="__lista_productos">
                                                {sucursal.combos_menos_vendidos.map((combo, i) => (
                                                    <div key={i} className="__item_lista">
                                                        <span className="__rank">{i + 1}.</span>
                                                        <span className="__nombre">{combo.nombre}</span>
                                                        <span className="__cantidad">{combo.cantidad}</span>
                                                    </div>
                                                ))}
                                            </div>
                                        ) : (
                                            <p style={{ textAlign: 'center', margin: '2rem 0' }}>No hay datos</p>
                                        )}
                                    </div>
                                ))}
                            </div>
                        </div>
                    </>
                )}
            </div>

            <div className="__informe_general_footer">
                <Boton onClick={() => manejarExportacion('excel')} habilitado descripcion={"Descargar EXCEL"} title="Descargar Excel"></Boton>
                <Boton onClick={() => manejarExportacion('pdf')} habilitado descripcion={"Descargar PDF"} title="Descargar PDF"></Boton>
            </div>
        </div>
    );
}